module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---- level 1: 4-bit group ORs and intra-nibble helpers -------------------
wire g0 = a_i[0]  | a_i[1]  | a_i[2]  | a_i[3];
wire g1 = a_i[4]  | a_i[5]  | a_i[6]  | a_i[7];
wire g2 = a_i[8]  | a_i[9]  | a_i[10] | a_i[11];
wire g3 = a_i[12] | a_i[13] | a_i[14] | a_i[15];
wire g4 = a_i[16] | a_i[17] | a_i[18] | a_i[19];
wire g5 = a_i[20] | a_i[21] | a_i[22] | a_i[23];
wire g6 = a_i[24] | a_i[25] | a_i[26] | a_i[27];
wire g7 = a_i[28] | a_i[29] | a_i[30] | a_i[31];

// u_k : winner inside nibble k has bit1 set
wire u0 = a_i[3]  | a_i[2];
wire u1 = a_i[7]  | a_i[6];
wire u2 = a_i[11] | a_i[10];
wire u3 = a_i[15] | a_i[14];
wire u4 = a_i[19] | a_i[18];
wire u5 = a_i[23] | a_i[22];
wire u6 = a_i[27] | a_i[26];
wire u7 = a_i[31] | a_i[30];

// v_k : winner inside nibble k has bit0 set
wire v0 = a_i[3]  | (~a_i[2]  & a_i[1]);
wire v1 = a_i[7]  | (~a_i[6]  & a_i[5]);
wire v2 = a_i[11] | (~a_i[10] & a_i[9]);
wire v3 = a_i[15] | (~a_i[14] & a_i[13]);
wire v4 = a_i[19] | (~a_i[18] & a_i[17]);
wire v5 = a_i[23] | (~a_i[22] & a_i[21]);
wire v6 = a_i[27] | (~a_i[26] & a_i[25]);
wire v7 = a_i[31] | (~a_i[30] & a_i[29]);

// ---- level 2: "any higher group set" prefix (balanced) -------------------
wire t3 = (g7 | g6) | (g5 | g4);   // |a_i[31:16]
wire t5 = g7 | g6;
wire t4 = (g7 | g6) | g5;
wire t2 = t3 | g3;
wire t1 = t3 | (g3 | g2);
wire t0 = t3 | (g3 | g2 | g1);

// ---- level 3: one-hot winning group --------------------------------------
wire e7 = g7;
wire e6 = g6 & ~g7;
wire e5 = g5 & ~t5;
wire e4 = g4 & ~t4;
wire e3 = g3 & ~t3;
wire e2 = g2 & ~t2;
wire e1 = g1 & ~t1;
wire e0 = g0 & ~t0;

// ---- output bits ---------------------------------------------------------
wire hit_0 = t0 | g0;

wire i4 = t3;
wire i3 = (g7 | g6) | (~t3 & (g3 | g2));
wire i2 = (e7 | e5) | (e3 | e1);
wire i1 = ((e7 & u7) | (e6 & u6) | (e5 & u5) | (e4 & u4)) |
          ((e3 & u3) | (e2 & u2) | (e1 & u1) | (e0 & u0));
wire i0 = ((e7 & v7) | (e6 & v6) | (e5 & v5) | (e4 & v4)) |
          ((e3 & v3) | (e2 & v2) | (e1 & v1) | (e0 & v0));

wire [5:0] chosen_0 = {hit_0, i4, i3, i2, i1, i0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen_0;
    end
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---- level 1 : nibble OR, top-pair OR, odd-position flag -----------------
wire g0 = a_i[0]  | a_i[1]  | a_i[2]  | a_i[3];
wire g1 = a_i[4]  | a_i[5]  | a_i[6]  | a_i[7];
wire g2 = a_i[8]  | a_i[9]  | a_i[10] | a_i[11];
wire g3 = a_i[12] | a_i[13] | a_i[14] | a_i[15];
wire g4 = a_i[16] | a_i[17] | a_i[18] | a_i[19];
wire g5 = a_i[20] | a_i[21] | a_i[22] | a_i[23];
wire g6 = a_i[24] | a_i[25] | a_i[26] | a_i[27];
wire g7 = a_i[28] | a_i[29] | a_i[30] | a_i[31];

wire u0 = a_i[3]  | a_i[2];
wire u1 = a_i[7]  | a_i[6];
wire u2 = a_i[11] | a_i[10];
wire u3 = a_i[15] | a_i[14];
wire u4 = a_i[19] | a_i[18];
wire u5 = a_i[23] | a_i[22];
wire u6 = a_i[27] | a_i[26];
wire u7 = a_i[31] | a_i[30];

wire v0 = a_i[3]  | (~a_i[2]  & a_i[1]);
wire v1 = a_i[7]  | (~a_i[6]  & a_i[5]);
wire v2 = a_i[11] | (~a_i[10] & a_i[9]);
wire v3 = a_i[15] | (~a_i[14] & a_i[13]);
wire v4 = a_i[19] | (~a_i[18] & a_i[17]);
wire v5 = a_i[23] | (~a_i[22] & a_i[21]);
wire v6 = a_i[27] | (~a_i[26] & a_i[25]);
wire v7 = a_i[31] | (~a_i[30] & a_i[29]);

// ---- level 2 : upper-half empty flag -------------------------------------
wire nt3 = ~(g7 | g6 | g5 | g4);          // no set bit in a_i[31:16]
wire hi4 = ~nt3;

// ---- half encoders written as flat products of level-1 literals ----------
wire hu = u7 | (u6 & ~g7) | (u5 & ~g7 & ~g6) | (u4 & ~g7 & ~g6 & ~g5);
wire lu = u3 | (u2 & ~g3) | (u1 & ~g3 & ~g2) | (u0 & ~g3 & ~g2 & ~g1);

wire hv = v7 | (v6 & ~g7) | (v5 & ~g7 & ~g6) | (v4 & ~g7 & ~g6 & ~g5);
wire lv = v3 | (v2 & ~g3) | (v1 & ~g3 & ~g2) | (v0 & ~g3 & ~g2 & ~g1);

wire hg = g7 | (g5 & ~g6 & ~g7);
wire lg = g3 | (g1 & ~g2 & ~g3);

// ---- outputs --------------------------------------------------------------
wire i4 = hi4;
wire i3 = (g7 | g6) | (nt3 & (g3 | g2));
wire i2 = hg | (nt3 & lg);
wire i1 = hu | (nt3 & lu);
wire i0 = hv | (nt3 & lv);
wire hit_0 = hi4 | (g3 | g2 | g1 | g0);

wire [5:0] chosen_0 = {hit_0, i4, i3, i2, i1, i0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen_0;
    end
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---- level 1 : pair ORs (every a_i bit drives exactly one of these) -------
wire q0  = a_i[1]  | a_i[0];
wire q1  = a_i[3]  | a_i[2];
wire q2  = a_i[5]  | a_i[4];
wire q3  = a_i[7]  | a_i[6];
wire q4  = a_i[9]  | a_i[8];
wire q5  = a_i[11] | a_i[10];
wire q6  = a_i[13] | a_i[12];
wire q7  = a_i[15] | a_i[14];
wire q8  = a_i[17] | a_i[16];
wire q9  = a_i[19] | a_i[18];
wire q10 = a_i[21] | a_i[20];
wire q11 = a_i[23] | a_i[22];
wire q12 = a_i[25] | a_i[24];
wire q13 = a_i[27] | a_i[26];
wire q14 = a_i[29] | a_i[28];
wire q15 = a_i[31] | a_i[30];

// ---- level 2 : byte ORs ---------------------------------------------------
wire b0 = (q0 | q1) | (q2 | q3);
wire b1 = (q4 | q5) | (q6 | q7);
wire b2 = (q8 | q9) | (q10 | q11);
wire b3 = (q12 | q13) | (q14 | q15);

// within-byte pair-index bits (winner pair inside each byte)
wire uu0 = q3  | q2;
wire uu1 = q7  | q6;
wire uu2 = q11 | q10;
wire uu3 = q15 | q14;

wire vv0 = q3  | (~q2  & q1);
wire vv1 = q7  | (~q6  & q5);
wire vv2 = q11 | (~q10 & q9);
wire vv3 = q15 | (~q14 & q13);

// odd-bit of the winning pair inside each byte (odd a_i bits: 2nd load)
wire w0 = a_i[7]  | (~q3  & a_i[5])  | (~q3  & ~q2  & a_i[3])  | (~q3  & ~q2  & ~q1  & a_i[1]);
wire w1 = a_i[15] | (~q7  & a_i[13]) | (~q7  & ~q6  & a_i[11]) | (~q7  & ~q6  & ~q5  & a_i[9]);
wire w2 = a_i[23] | (~q11 & a_i[21]) | (~q11 & ~q10 & a_i[19]) | (~q11 & ~q10 & ~q9  & a_i[17]);
wire w3 = a_i[31] | (~q15 & a_i[29]) | (~q15 & ~q14 & a_i[27]) | (~q15 & ~q14 & ~q13 & a_i[25]);

// ---- output bits ----------------------------------------------------------
wire i4 = b3 | b2;
wire i3 = b3 | (b1 & ~b2 & ~b3);
wire i2 = uu3 | (uu2 & ~b3) | (uu1 & ~b3 & ~b2) | (uu0 & ~b3 & ~b2 & ~b1);
wire i1 = vv3 | (vv2 & ~b3) | (vv1 & ~b3 & ~b2) | (vv0 & ~b3 & ~b2 & ~b1);
wire i0 = w3  | (w2  & ~b3) | (w1  & ~b3 & ~b2) | (w0  & ~b3 & ~b2 & ~b1);
wire hit_0 = (b3 | b2) | (b1 | b0);

wire [5:0] chosen_0 = {hit_0, i4, i3, i2, i1, i0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen_0;
    end
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

wire hit_0 = |a_i[31:0];
wire [4:0] idx_0 = a_i[31] ? 5'd31 : a_i[30] ? 5'd30 : a_i[29] ? 5'd29 : a_i[28] ? 5'd28 : a_i[27] ? 5'd27 : a_i[26] ? 5'd26 : a_i[25] ? 5'd25 : a_i[24] ? 5'd24 : a_i[23] ? 5'd23 : a_i[22] ? 5'd22 : a_i[21] ? 5'd21 : a_i[20] ? 5'd20 : a_i[19] ? 5'd19 : a_i[18] ? 5'd18 : a_i[17] ? 5'd17 : a_i[16] ? 5'd16 : a_i[15] ? 5'd15 : a_i[14] ? 5'd14 : a_i[13] ? 5'd13 : a_i[12] ? 5'd12 : a_i[11] ? 5'd11 : a_i[10] ? 5'd10 : a_i[9] ? 5'd9 : a_i[8] ? 5'd8 : a_i[7] ? 5'd7 : a_i[6] ? 5'd6 : a_i[5] ? 5'd5 : a_i[4] ? 5'd4 : a_i[3] ? 5'd3 : a_i[2] ? 5'd2 : a_i[1] ? 5'd1 : a_i[0] ? 5'd0 : 5'd0;

wire [5:0] chosen_0 = hit_0 ? {1'b1, idx_0} : 6'd0;

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen_0;
    end
end
endmodule
